/** Statuses that count as closed for stats, digests and overdue checks. */
export const CLOSED_ISSUE_STATUSES: readonly IssueStatus[] = ["done", "canceled"];

/**
 * The two status groups the filter vocabulary recognises alongside the six
 * literal statuses (ADR 0009). `open` is every status that is not closed.
 */
export const ISSUE_STATUS_GROUPS = ["open", "closed"] as const;
export type IssueStatusGroup = (typeof ISSUE_STATUS_GROUPS)[number];

/** A value the issue filter's `status` dimension accepts: a literal status or a group. */
export type IssueStatusFilterValue = IssueStatus | IssueStatusGroup;

export function isIssueStatusFilterValue(
  value: string,
): value is IssueStatusFilterValue {
  return (
    (ISSUE_STATUSES as readonly string[]).includes(value) ||
    (ISSUE_STATUS_GROUPS as readonly string[]).includes(value)
  );
}

/**
 * Expands `open` / `closed` into their member statuses so the codec, the
 * schema and the repository all end up filtering on the same literal set
 * regardless of which one a given `status=…` value arrived at first.
 */
export function expandIssueStatusFilter(
  values: readonly IssueStatusFilterValue[],
): readonly IssueStatus[] {
  const expanded = new Set<IssueStatus>();
  for (const value of values) {
    if (value === "closed") {
      for (const status of CLOSED_ISSUE_STATUSES) expanded.add(status);
    } else if (value === "open") {
      for (const status of ISSUE_STATUSES) {
        if (!CLOSED_ISSUE_STATUSES.includes(status)) expanded.add(status);
      }
    } else {
      expanded.add(value);
    }
  }
  return [...expanded];
}

