const CALENDAR_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Turns a `due_before` filter value into the exclusive cutoff the repository
 * compares against. A bare calendar date reads as UTC and includes the whole
 * day, so the cutoff is midnight of the *following* day; a full timestamp is
 * already the exclusive cutoff, unchanged (ADR 0009).
 */
export function dueBeforeCutoff(value: string): IsoTimestamp {
  if (CALENDAR_DATE.test(value)) {
    return toIsoTimestamp(
      new Date(parseIso(toIsoTimestamp(`${value}T00:00:00.000Z`)).getTime() + DAY_MS),
    );
  }
  return toIsoTimestamp(new Date(value));
}

