export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

/** `open` / `closed` — the status groups the filter vocabulary accepts alongside the six literal statuses (ADR 0009). */
export const issueStatusGroupSchema = z.enum(ISSUE_STATUS_GROUPS);

export const issueStatusFilterSchema = z.union([
  issueStatusSchema,
  issueStatusGroupSchema,
]);

/** A user id, or the literal `"me"`, resolved by the service against the acting user. */
export const assigneeFilterSchema = z.union([z.literal("me"), userIdSchema]);

/** `due_before`: a calendar date (whole day inclusive) or a full ISO timestamp. */
export const dueBeforeFilterSchema = z.union([z.iso.date(), isoTimestampSchema]);

