167	export async function listIssues(
168	  input: ResolvedIssueFilter,
169	): Promise<Page<Issue>> {
170	  const db = getDb();
171	  const filters = issueFilters(input);
172	  const sort = { sortColumn: issues.createdAt, idColumn: issues.id };
173	
174	  const total = db
175	    .select({ value: count() })
176	    .from(issues)
177	    .where(and(...filters))
178	    .get();
179	
180	  const rows = db
181	    .select()
182	    .from(issues)
183	    .where(and(...filters, ...compact(keysetPredicate(sort, input.cursor))))
184	    .orderBy(desc(issues.createdAt), desc(issues.id))
185	    .limit(probeLimit(input.limit))
186	    .all();
187	
188	  const labels = await listLabelsForIssues(
189	    input.orgId,
190	    rows.map((row) => row.id as IssueId),
191	  );
192	
193	  return toPage(
194	    rows,
195	    input.limit,
196	    total?.value ?? 0,
197	    (row) => toIssue(row, (labels[row.id] ?? []).map((label) => label.id)),
198	    (row) => ({ id: row.id, sortValue: row.createdAt }),
199	  );
200	}
201	
202	/**
203	 * The list view needs comment and attachment counts per row. Two grouped
204	 * queries beat N+1 round trips, so the counts are folded in afterwards.
205	 */
206	export async function listIssuesWithRelations(
207	  input: ResolvedIssueFilter,
208	): Promise<Page<IssueWithRelations>> {
209	  const db = getDb();
210	  const page = await listIssues(input);
