import { describe, expect, it } from "vitest";
import {
  parseIssueFilterParams,
  issueFilterToParams,
  readableParamsFromRecord,
} from "@/hooks/issue-filter-params";
import { issueFilterSchema } from "@/schemas/issue";
import { dueBeforeCutoff } from "@/lib/date";
import { expandIssueStatusFilter } from "@/types/issue";
import { ORG_A } from "./helpers/factories";

function params(query: string): URLSearchParams {
  return new URLSearchParams(query);
}

describe("sanity: ADR 0009", () => {
  it("expands status groups", () => {
    expect(parseIssueFilterParams(params("status=open")).status).toEqual(
      expandIssueStatusFilter(["open"]),
    );
    expect(parseIssueFilterParams(params("status=closed")).status).toEqual([
      "done",
      "canceled",
    ]);
  });

  it("schema accepts status groups directly", () => {
    const parsed = issueFilterSchema.parse({ orgId: ORG_A, status: ["open"] });
    expect(parsed.status).toEqual(["open"]);
  });

  it("schema accepts 'me' for assignee/author", () => {
    const parsed = issueFilterSchema.parse({ orgId: ORG_A, assigneeId: "me", authorId: "me" });
    expect(parsed.assigneeId).toBe("me");
    expect(parsed.authorId).toBe("me");
  });

  it("schema accepts a bare calendar date for dueBefore", () => {
    const parsed = issueFilterSchema.parse({ orgId: ORG_A, dueBefore: "2026-03-15" });
    expect(parsed.dueBefore).toBe("2026-03-15");
  });

  it("dueBeforeCutoff includes the whole day for a date, exact instant for a timestamp", () => {
    expect(dueBeforeCutoff("2026-03-15")).toBe("2026-03-16T00:00:00.000Z");
    expect(dueBeforeCutoff("2026-03-15T12:00:00.000Z")).toBe(
      "2026-03-15T12:00:00.000Z",
    );
  });

  it("archived=only round-trips", () => {
    const filter = parseIssueFilterParams(params("archived=only"));
    expect(filter.archivedOnly).toBe(true);
    expect(issueFilterToParams(filter).archived).toBe("only");
  });

  it("readableParamsFromRecord adapts a Next.js searchParams record", () => {
    const readable = readableParamsFromRecord({ status: "open", label: ["a", "b"] });
    expect(readable.get("status")).toBe("open");
    expect(readable.get("label")).toBe("a,b");
    expect(readable.get("missing")).toBeNull();
  });
});

